const r1 = authenticateHeader('Bearer ' + validPayload + '.' + secret, secret);
const r2 = authenticateHeader('Bearer ' + expiredPayload + '.' + secret, secret);
const r3 = authenticateHeader('Bearer ' + validPayload + '.SECRET_wrong', secret);
const r4 = authenticateHeader('Basic abc', secret);
