if (!r1.valid || r1.userId !== 'user_42') process.exit(1);
if (r2.valid || !r2.reason) process.exit(2);
if (r3.valid || r3.reason !== 'BAD_SIGNATURE') process.exit(3);
if (r4.valid || !r4.reason) process.exit(4);
